                            run_span.record("otel.status_code", "ERROR");
                            failure.set(err);
                            yield crate::AgentEvent::RunFailed { error: msg };
                            return;
                        }

                        yield crate::AgentEvent::HandoffItem {
                            from: agent_name.clone(),
                            to: target.clone(),
                        };
